import{_ as n,C as s,o as t,c as r,a3 as o,b as i,w as a,a as c,E as h,a4 as l}from"./chunks/framework.B02wg2PO.js";const y=JSON.parse('{"title":"The Sandbox","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/sandbox.md","filePath":"concepts/sandbox.md"}'),p={name:"concepts/sandbox.md"};function u(g,e,m,b,k,f){const d=s("Mermaid");return t(),r("div",null,[e[1]||(e[1]=o('<h1 id="the-sandbox" tabindex="-1">The Sandbox <a class="header-anchor" href="#the-sandbox" aria-label="Permalink to &quot;The Sandbox&quot;">​</a></h1><p>The sandbox runs a custom agent&#39;s Claude session inside a locked-down, disposable Docker container instead of in the Saidi process. Its job is filesystem and credential containment: an agent&#39;s <code>Bash</code>, <code>Read</code>, <code>Write</code> and <code>Edit</code> calls should not be able to reach another tenant&#39;s data on disk, and should not see the host environment that holds the database URI and the master key.</p><p>It is <strong>off by default</strong>. With <code>SAIDI_SANDBOX</code> unset, agents execute in-host and the only thing standing between a model-written shell command and your disk is the tool gate described in <a href="/docs/concepts/modes-and-permissions">Modes &amp; Permissions</a>.</p><h2 id="request-path-when-saidi-sandbox-1" tabindex="-1">Request path when <code>SAIDI_SANDBOX=1</code> <a class="header-anchor" href="#request-path-when-saidi-sandbox-1" aria-label="Permalink to &quot;Request path when `SAIDI_SANDBOX=1`&quot;">​</a></h2>',4)),(t(),i(l,null,{default:a(()=>[h(d,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20D%5B%22Custom-agent%20delegation%5Cn(runCustomAgent)%22%5D%20--%3E%20H%7B%22has%20runId%3F%22%7D%0A%20%20%20%20H%20--%3E%7Cyes%7C%20PL%5B%22Per-run%20pooled%20container%5Cndocker%20run%20-d%20%E2%80%A6%20sleep%20infinity%22%5D%0A%20%20%20%20H%20--%3E%7Cno%2C%20main%20chat%7C%20EP%5B%22Ephemeral%20container%5Cndocker%20run%20--rm%20-i%22%5D%0A%20%20%20%20PL%20--%3E%20EX%5B%22docker%20exec%20-i%5Cnworks%20from%20%2Fworkspace%2F%3Cagent%3E%22%5D%0A%20%20%20%20EP%20--%3E%20RUN%5B%22Runs%20to%20completion%2C%5Cnexits%20with%20the%20command%22%5D%0A%20%20%20%20EX%20--%3E%20W%5B%22worker.js%5Cn(bundled%20dist%2Fsandbox-worker.js)%22%5D%0A%20%20%20%20RUN%20--%3E%20W%0A%20%20%20%20W%20--%3E%7Cstdout%3A%20status%2Fdelta%2Ftext%2Fsession%2Fusage%2Fresult%7C%20HOST%5B%22Host%20reads%5Cnnewline-delimited%20JSON%20events%22%5D%0A%20%20%20%20HOST%20--%3E%20SWEEP%5B%22%2Frun%2Foutput%20swept%20into%5Cnrun%20assets%20after%20return%22%5D%0A%20%20%20%20D%20-.-%3E%7Cproject%20agent%20ask%2Fwork%2C%5CnPRIME%2C%20mechanical%20checks%7C%20SKIP%5B%22NOT%20sandboxed%20%E2%80%94%5Cnruns%20in-host%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o(`<h2 id="what-is-sandboxed-and-what-is-not" tabindex="-1">What is sandboxed, and what is not <a class="header-anchor" href="#what-is-sandboxed-and-what-is-not" aria-label="Permalink to &quot;What is sandboxed, and what is not&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Sandboxed?</th></tr></thead><tbody><tr><td>Custom-agent Claude delegations (<code>runCustomAgent</code>)</td><td>Yes, when <code>SAIDI_SANDBOX=1</code></td></tr><tr><td>Project-agent repo work (<code>ask</code> / <code>work</code> on a registered repo)</td><td>No — runs in-host on the repo checkout</td></tr><tr><td>PRIME&#39;s own turns</td><td>No</td></tr><tr><td>Mechanical task <code>checks</code></td><td>No — see <a href="#checks-are-not-sandboxed">Checks are not sandboxed</a></td></tr></tbody></table><p>So the sandbox is a boundary around <em>one class of worker</em>, not around the whole orchestrator. Turning it on does not make every command in a run containerised.</p><h2 id="two-container-shapes" tabindex="-1">Two container shapes <a class="header-anchor" href="#two-container-shapes" aria-label="Permalink to &quot;Two container shapes&quot;">​</a></h2><p><strong>Per-run container (pooled).</strong> When the delegation carries a <code>runId</code>, the pool starts one detached container for the whole run (<code>docker run -d … sleep infinity</code>) and drives each delegation through <code>docker exec -i</code>. Agents are separated inside it by directory — each works from <code>/workspace/&lt;agent&gt;</code>. The container holds no durable state: every directory it can write is a host bind mount, so it can be force-removed and lazily recreated without losing work.</p><p><strong>Ephemeral container.</strong> Without a <code>runId</code> (main chat), each call gets its own <code>docker run --rm -i</code> container that exits when the command does.</p><h3 id="mounts-in-the-per-run-container" tabindex="-1">Mounts in the per-run container <a class="header-anchor" href="#mounts-in-the-per-run-container" aria-label="Permalink to &quot;Mounts in the per-run container&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Container path</th><th>Host source</th><th>Mode</th></tr></thead><tbody><tr><td><code>/workspace</code></td><td>the run&#39;s work root</td><td>rw</td></tr><tr><td><code>/run/assets</code></td><td>the run&#39;s assets dir (prior files, uploads)</td><td>ro</td></tr><tr><td><code>/run/output</code></td><td>the run&#39;s output dir (deliverables)</td><td>rw</td></tr><tr><td><code>/run/shared</code></td><td>cross-agent handoff notes</td><td>rw</td></tr><tr><td><code>/run/agent-config</code></td><td>per-agent <code>CLAUDE_CONFIG_DIR</code></td><td>rw</td></tr><tr><td><code>/agents</code></td><td>the org&#39;s agent homes</td><td>ro</td></tr></tbody></table><p>The ephemeral container gets one mount only: the delegation&#39;s <code>workDir</code> at <code>/workspace</code>.</p><p>A sandboxed agent&#39;s system prompt is rewritten to describe these container paths instead of host paths, and it is told to save deliverables into <code>/run/output</code>, which the engine sweeps into the run&#39;s assets after the delegation returns.</p><h2 id="isolation-the-flags-actually-give-you" tabindex="-1">Isolation the flags actually give you <a class="header-anchor" href="#isolation-the-flags-actually-give-you" aria-label="Permalink to &quot;Isolation the flags actually give you&quot;">​</a></h2><p>Every Saidi container — pooled or ephemeral — is started with the same hardening argument set:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Value</th><th>Effect</th></tr></thead><tbody><tr><td><code>--user</code></td><td>Saidi&#39;s own uid:gid (falls back to <code>1000:1000</code>)</td><td>Non-root inside the container</td></tr><tr><td><code>--cap-drop</code></td><td><code>ALL</code></td><td>No Linux capabilities</td></tr><tr><td><code>--security-opt</code></td><td><code>no-new-privileges</code></td><td>setuid binaries cannot escalate</td></tr><tr><td><code>--read-only</code></td><td>—</td><td>Immutable root filesystem</td></tr><tr><td><code>--tmpfs</code></td><td><code>/tmp:rw,noexec,nosuid,size=512m</code></td><td>The only writable path outside the mounts</td></tr><tr><td><code>-v</code></td><td>the mounts above</td><td>The only host paths visible</td></tr><tr><td><code>--memory</code> / <code>--memory-swap</code></td><td><code>2g</code> / same</td><td>No swap beyond the memory cap</td></tr><tr><td><code>--cpus</code></td><td><code>2</code></td><td>CPU cap</td></tr><tr><td><code>--pids-limit</code></td><td><code>512</code></td><td>A fork bomb cannot exhaust host PIDs</td></tr></tbody></table><p>Read this list literally. It is a hardened container, not a VM, and the honest caveats are:</p><ul><li><strong>The container runs as Saidi&#39;s own uid.</strong> That is deliberate — a mismatched uid cannot read the workspace Saidi created for it — but it means the strength of the boundary depends on Saidi itself not running as root.</li><li><strong>The network is not <code>none</code> in practice.</strong> The primitive defaults to <code>--network none</code>, but the worker has to reach the LLM, so the run path always starts the container on <code>bridge</code> (or <code>host</code>, if <code>SAIDI_SANDBOX_NETWORK=host</code>). That is general egress. The supported way to narrow it today is to point the host at a filtering proxy: <code>HTTPS_PROXY</code>, <code>HTTP_PROXY</code>, <code>NO_PROXY</code> (and their lowercase forms) plus <code>NODE_EXTRA_CA_CERTS</code> are forwarded into the container so the worker&#39;s calls go through the same policy.</li><li><strong>Nothing here isolates the code the agent is <em>reading</em>.</strong> The workspace is a real host directory, mounted read-write.</li></ul><h3 id="the-container-s-environment" tabindex="-1">The container&#39;s environment <a class="header-anchor" href="#the-container-s-environment" aria-label="Permalink to &quot;The container&#39;s environment&quot;">​</a></h3><p>The container&#39;s environment is <em>only</em> what the host explicitly passes — no host env is inherited. The allow-list is:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ANTHROPIC_API_KEY   ANTHROPIC_AUTH_TOKEN   ANTHROPIC_BASE_URL   ANTHROPIC_MODEL</span></span>
<span class="line"><span>CLAUDE_CODE_OAUTH_TOKEN</span></span>
<span class="line"><span>ANTHROPIC_DEFAULT_OPUS_MODEL   ANTHROPIC_DEFAULT_SONNET_MODEL</span></span>
<span class="line"><span>ANTHROPIC_DEFAULT_HAIKU_MODEL  ANTHROPIC_DEFAULT_FABLE_MODEL</span></span>
<span class="line"><span>ANTHROPIC_SMALL_FAST_MODEL</span></span>
<span class="line"><span>HTTPS_PROXY  HTTP_PROXY  NO_PROXY  https_proxy  http_proxy  no_proxy</span></span>
<span class="line"><span>NODE_EXTRA_CA_CERTS</span></span></code></pre></div><p>Plus <code>CLAUDE_CONFIG_DIR</code>, which the pool sets to <code>/run/agent-config/&lt;agent&gt;</code>. Absent variables are simply not set. The database URI, the master key, every <code>SAIDI_*</code> variable and any other tenant&#39;s secrets are not among them.</p><p>If the run resolved a custom provider profile, that profile&#39;s env is merged over the base set: a defined value overrides, an undefined value deletes the base key.</p><h2 id="building-and-launching-the-worker" tabindex="-1">Building and launching the worker <a class="header-anchor" href="#building-and-launching-the-worker" aria-label="Permalink to &quot;Building and launching the worker&quot;">​</a></h2><p>The thing that runs inside the container is a single bundled file. Two steps:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:sandbox-worker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/orchestrator/sandbox/Dockerfile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saidi-sandbox:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span></code></pre></div><p>The first step is esbuild: <code>src/orchestrator/sandbox/worker.ts</code> is bundled to <code>dist/sandbox-worker.js</code> as minified ESM targeting Node 20. Saidi&#39;s own source is inlined; npm packages stay <strong>external</strong> on purpose, because the Agent SDK spawns a platform-specific CLI binary and bundling the host&#39;s macOS build would not run in a Linux container.</p><p>The image is <code>node:22-slim</code> plus <code>git</code>, <code>ca-certificates</code>, <code>curl</code>, <code>ripgrep</code> and <code>tini</code> (PID 1, so orphaned subprocesses get reaped). The Agent SDK is installed from npm inside the image — pinned in <code>worker-deps.json</code>, which must match the version in the root <code>package.json</code> — so the Linux build of the CLI is fetched. The bundle lands at <code>/opt/saidi/worker.js</code>, and the image&#39;s own user is <code>1000:1000</code>. No <code>CMD</code> is set; the command (<code>node /opt/saidi/worker.js</code>) comes from the launcher.</p><p>Set the image tag per deployment with <code>SAIDI_SANDBOX_IMAGE</code>; see <a href="/docs/reference/configuration">Configuration</a> for the full env var list.</p><h3 id="boot-preflight" tabindex="-1">Boot preflight <a class="header-anchor" href="#boot-preflight" aria-label="Permalink to &quot;Boot preflight&quot;">​</a></h3><p>At startup Saidi probes <code>docker info</code> and <code>docker image inspect</code> (4-second bound each) and prints one of three things: sandbox off, sandbox on and runnable, or sandbox enabled but broken. An enabled-but-unbuilt image fails loudly at boot rather than silently on every delegation. When the sandbox is on and healthy, boot also sweeps containers labelled <code>saidi.sandbox=1</code> that a prior crash left behind, and starts the idle reaper.</p><h2 id="the-host↔worker-protocol" tabindex="-1">The host↔worker protocol <a class="header-anchor" href="#the-host↔worker-protocol" aria-label="Permalink to &quot;The host↔worker protocol&quot;">​</a></h2><p>Nothing but JSON crosses the boundary — the host cannot hand a JS closure (a tool gate, an in-process MCP server, a callback) to a container. The host writes one <code>SandboxJob</code> to stdin; the worker writes newline-delimited events to stdout. Any stdout line that is not a JSON object is treated as log noise, never as an event.</p><table tabindex="0"><thead><tr><th>Event</th><th>Carries</th></tr></thead><tbody><tr><td><code>status</code></td><td><code>msg</code> + optional <code>detail</code> (the exact tool call, e.g. <code>$ npm test</code>)</td></tr><tr><td><code>delta</code></td><td>one streamed text fragment</td></tr><tr><td><code>text</code></td><td>a completed text block</td></tr><tr><td><code>session</code></td><td>the SDK session id, for resume</td></tr><tr><td><code>usage</code></td><td>token counts, <code>costUsd</code>, and every model the turn touched</td></tr><tr><td><code>result</code></td><td>the final report text + <code>isError</code></td></tr><tr><td><code>error</code></td><td>a fatal message</td></tr></tbody></table><p>The job carries the task text (with any memory block already injected), the system prompt, the permission policy, the model, the actor name, the cwd, and a session id to resume. The <code>usage</code> event is what lets a sandboxed call be debited like any other, exactly like an in-host call.</p><h2 id="permissions-inside-the-container" tabindex="-1">Permissions inside the container <a class="header-anchor" href="#permissions-inside-the-container" aria-label="Permalink to &quot;Permissions inside the container&quot;">​</a></h2><p>The worker rebuilds the permission gate from the serialized policy, so the tiers behave the same as in-host:</p><table tabindex="0"><thead><tr><th><code>permission</code></th><th>Allowed tools</th><th>Denial message</th></tr></thead><tbody><tr><td><code>read-only</code></td><td><code>Read</code>, <code>Grep</code>, <code>Glob</code></td><td><code>read-only agent: &quot;&lt;tool&gt;&quot; is not permitted.</code></td></tr><tr><td><code>custom</code></td><td>exactly the agent&#39;s <code>tools</code> list</td><td><code>&quot;&lt;tool&gt;&quot; is not in this agent&#39;s permitted tools.</code></td></tr><tr><td><code>all</code></td><td>everything the runtime offers</td><td>—</td></tr></tbody></table><p>Two further constraints apply to every sandboxed worker regardless of tier: <code>ScheduleWakeup</code> is disallowed, and <code>settingSources</code> is empty — no filesystem settings from the host or the user&#39;s global Claude configuration are loaded.</p><p>What the sandboxed path does <strong>not</strong> get, which the in-host path does: MCP servers. The worker is deliberately dependency-light and starts the SDK with no MCP servers and no agent-local plugin directory, so Saidi&#39;s own <code>remember</code> tool is unavailable inside the container. Agent reference material is reached through the read-only <code>/agents</code> mount instead.</p><h2 id="timeouts-reaping-and-failure" tabindex="-1">Timeouts, reaping, and failure <a class="header-anchor" href="#timeouts-reaping-and-failure" aria-label="Permalink to &quot;Timeouts, reaping, and failure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th><th>Where</th></tr></thead><tbody><tr><td>Delegation wall clock</td><td>30 minutes (default)</td><td>force-kills the exec/run and cleans up</td></tr><tr><td>Idle container TTL</td><td>15 minutes, swept every 60s</td><td>never reaps a container with a delegation in flight</td></tr><tr><td>Docker availability probe</td><td>4 seconds</td><td>boot preflight</td></tr><tr><td>tmpfs <code>/tmp</code></td><td>512 MB</td><td>container</td></tr></tbody></table><p>Because killing a <code>docker exec</code> client does not stop the process inside the container, timeout and abort run an explicit cleanup. In a shared per-run container that cleanup is conditional: the container is torn down only when the timing-out exec is the <strong>last</strong> one in flight. If sibling agents are still working, just this exec client is dropped — their scratch survives, and a later call lazily recreates the container from the host mounts if it did go away.</p><p>A run&#39;s container is disposed when the run reaches <code>done</code>, <code>cancelled</code> or <code>error</code>, and when the run is deleted. Every tracked container is removed on process shutdown.</p><p>When the container cannot run at all — daemon down, image missing, timeout, worker crash, or a worker that emitted no result — the delegation comes back with an explicit non-retryable message:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Environment error (sandbox): &lt;reason&gt;. The agent could not run to completion —</span></span>
<span class="line"><span>this is an infrastructure/environment problem it cannot fix by trying again.</span></span>
<span class="line"><span>Do NOT re-delegate this task; report the failure to the operator.</span></span></code></pre></div><p>That wording exists so PRIME escalates instead of burning the task&#39;s attempt budget re-delegating into the same broken daemon. A timeout reports the reason as <code>the agent timed out (30-minute cap)</code>.</p><h2 id="checks-are-not-sandboxed" tabindex="-1">Checks are not sandboxed <a class="header-anchor" href="#checks-are-not-sandboxed" aria-label="Permalink to &quot;Checks are not sandboxed&quot;">​</a></h2><p>A task&#39;s mechanical <code>checks</code> and a sandboxed delegation are two different containment problems solved two different ways, and it is worth being exact about which is which.</p><p>Checks run <strong>on the host</strong>, via <code>bash -c</code> in the evidence working tree — not inside any container, even when the sandbox is on. They also never pass through <code>canUseTool</code>, so no worker permission gate applies to them. What contains them instead is a static allow-list applied before the command is ever run:</p><table tabindex="0"><thead><tr><th>Constraint</th><th>Rule</th></tr></thead><tbody><tr><td>Programs</td><td>An allow-list of inspection tools (<code>test</code>, <code>ls</code>, <code>cat</code>, <code>grep</code>, <code>rg</code>, <code>diff</code>, <code>jq</code>, <code>npm</code>, <code>node</code>, <code>git</code>, …). Anything else is refused</td></tr><tr><td>Invocation</td><td>No program by path — <code>/bin/sh</code> is rejected on its basename</td></tr><tr><td>Substitution</td><td>No <code>$(…)</code>, backticks or <code>\${…}</code></td></tr><tr><td>Writes</td><td>No redirection at all, and no <code>tee</code>; no <code>sed -i</code></td></tr><tr><td>Interpreters</td><td>No <code>-e</code>, <code>-c</code>, <code>--eval</code>, <code>--command</code>, <code>--print</code> on <code>node</code>/<code>python</code>/<code>python3</code></td></tr><tr><td>Git</td><td>Read-only subcommands only (<code>status</code>, <code>log</code>, <code>show</code>, <code>diff</code>, <code>rev-parse</code>, …)</td></tr><tr><td>Size</td><td>At most 3 checks per task, 500 characters each</td></tr><tr><td>Timeout</td><td>60 seconds per check, 4 MB of captured output</td></tr><tr><td>Environment</td><td>The worker env minus every variable whose name matches <code>KEY</code>, <code>TOKEN</code>, <code>SECRET</code>, <code>PASSWORD</code>, <code>CREDENTIAL</code>, <code>AUTH</code> or <code>SESSION</code> — and <code>bash -c</code>, never <code>-lc</code>, so a login shell cannot re-export what was just stripped</td></tr></tbody></table><p>Every segment of a pipeline is validated, not just the first. A check that violates any of these is <strong>dropped, not run</strong> — which fails open to the model verifier, so removing a check can never turn into an easier pass. Exit code decides the verdict; the output is captured for the report but never parsed.</p><p>The practical consequence: enabling the sandbox contains what an <em>agent</em> does. It does not change what a model-authored check can do to the host. Both surfaces need their own posture — see <a href="/docs/guides/guardrails">Approval &amp; Spend Guardrails</a>.</p><h2 id="operating-notes" tabindex="-1">Operating notes <a class="header-anchor" href="#operating-notes" aria-label="Permalink to &quot;Operating notes&quot;">​</a></h2><ul><li>Turning the sandbox on changes what a delegation can see. A prompt that referred to host paths will not find them; sandboxed agents are told about <code>/workspace</code>, <code>/run/assets</code>, <code>/run/output</code>, <code>/run/shared</code> and <code>/agents</code> instead.</li><li>Give a thrash-prone fleet more headroom with <code>SAIDI_SANDBOX_MEMORY</code> and <code>SAIDI_SANDBOX_CPUS</code>; the pid limit is fixed at 512.</li><li><code>SAIDI_AGENTS_DIR</code> overrides which directory is mounted read-only at <code>/agents</code>.</li><li>If delegations start failing immediately after enabling it, check the boot line first — a missing image and an unreachable daemon produce different warnings, and both name the rebuild command.</li></ul><p>See also: <a href="/docs/concepts/runs">Runs</a> · <a href="/docs/concepts/delegation">Delegation</a> · <a href="/docs/operations/troubleshooting">Troubleshooting</a></p>`,53))])}const x=n(p,[["render",u]]);export{y as __pageData,x as default};
